// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {LocalQuote} from "../interfaces/ILocalAdapter.sol";

error InvalidUniswapQuote();
error UniswapQuoteResult(uint256 _amountIn, uint256 _amountOut);

/// @title UniswapQuote
/// @author Agustin Aguilar
/// @notice Revert payload codec used by Uniswap v3/v4 quote simulations
library UniswapQuote {
  function revertQuote(uint256 _amountIn, uint256 _amountOut) internal pure {
    revert UniswapQuoteResult(_amountIn, _amountOut);
  }

  function decode(bytes memory _reason) internal pure returns (LocalQuote memory _quote) {
    if (_reason.length != 68) {
      _revertRaw(_reason);
    }

    bytes4 selector;
    uint256 amountIn;
    uint256 amountOut;
    assembly ("memory-safe") {
      selector := mload(add(_reason, 0x20))
      amountIn := mload(add(_reason, 0x24))
      amountOut := mload(add(_reason, 0x44))
    }

    if (selector != UniswapQuoteResult.selector) {
      _revertRaw(_reason);
    }

    return LocalQuote({amountIn: amountIn, amountOut: amountOut});
  }

  function _revertRaw(bytes memory _reason) private pure {
    if (_reason.length == 0) {
      revert InvalidUniswapQuote();
    }

    assembly ("memory-safe") {
      revert(add(_reason, 0x20), mload(_reason))
    }
  }
}

