// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {LocalAdapter} from "./LocalAdapter.sol";
import {SwapLimits} from "./SwapLimits.sol";
import {InvalidUniswapQuote, UniswapQuote} from "./UniswapQuote.sol";
import {LocalQuote} from "../interfaces/ILocalAdapter.sol";
import {IUniswapV4PoolManager, UniswapV4PoolKey, UniswapV4SwapParams} from "../interfaces/IUniswapV4PoolManager.sol";
import {IUniswapV4UnlockCallback} from "../interfaces/IUniswapV4UnlockCallback.sol";

/// @title UniswapV4Adapter
/// @author Agustin Aguilar
/// @notice Swap adapter for single-pool Uniswap v4 exact-input swaps
contract UniswapV4Adapter is LocalAdapter, IUniswapV4UnlockCallback {
  uint160 private constant MIN_SQRT_RATIO = 4_295_128_739;
  uint160 private constant MAX_SQRT_RATIO = 1_461_446_703_485_210_103_287_273_052_203_988_822_378_723_970_342;
  uint24 private constant DYNAMIC_FEE_FLAG = 0x800000;
  uint24 private constant MAX_LP_FEE = 1_000_000;
  uint160 private constant ALL_HOOK_MASK = (1 << 14) - 1;
  uint160 private constant AFTER_ADD_LIQUIDITY_FLAG = 1 << 10;
  uint160 private constant AFTER_REMOVE_LIQUIDITY_FLAG = 1 << 8;
  uint160 private constant BEFORE_SWAP_FLAG = 1 << 7;
  uint160 private constant AFTER_SWAP_FLAG = 1 << 6;
  uint160 private constant BEFORE_SWAP_RETURNS_DELTA_FLAG = 1 << 3;
  uint160 private constant AFTER_SWAP_RETURNS_DELTA_FLAG = 1 << 2;
  uint160 private constant AFTER_ADD_LIQUIDITY_RETURNS_DELTA_FLAG = 1 << 1;
  uint160 private constant AFTER_REMOVE_LIQUIDITY_RETURNS_DELTA_FLAG = 1;

  struct UnlockData {
    address route;
    address inbox;
    address tokenIn;
    address tokenOut;
    uint256 amountIn;
    bool quote;
    uint160 sqrtPriceLimitX96;
  }

  IUniswapV4PoolManager public immutable POOL_MANAGER;
  uint24 public immutable FEE;
  int24 public immutable TICK_SPACING;
  address public immutable HOOKS;

  event UniswapV4RouteExecuted(
    address indexed _inbox,
    address indexed _tokenIn,
    address indexed _tokenOut,
    uint24 _fee,
    int24 _tickSpacing,
    address _hooks,
    uint256 _amountIn,
    uint256 _amountOut
  );

  error ZeroAddress();
  error InvalidFee(uint24 _fee);
  error InvalidTickSpacing();
  error InvalidHooks(address _hooks);
  error InvalidAmount();
  error InvalidConsumedAmount(uint256 _expected, uint256 _actual);
  error InvalidSettlementAmount(uint256 _expected, uint256 _actual);
  error UnsupportedRoute(address _tokenIn, address _tokenOut);
  error UnauthorizedPoolManager(address _sender);
  error InvalidSwapDelta(int256 _swapDelta);

  constructor(address _poolManager, uint24 _fee, int24 _tickSpacing, address _hooks) {
    if (_poolManager == address(0)) {
      revert ZeroAddress();
    }
    if (!_isValidFee(_fee)) {
      revert InvalidFee(_fee);
    }
    if (_tickSpacing <= 0) {
      revert InvalidTickSpacing();
    }
    _validateHooks(_fee, _hooks);

    POOL_MANAGER = IUniswapV4PoolManager(_poolManager);
    FEE = _fee;
    TICK_SPACING = _tickSpacing;
    HOOKS = _hooks;
  }

  /// @notice Quotes a Uniswap v4 exact-input swap for an explicit non-zero input amount.
  function quote(address _tokenIn, address _tokenOut, uint256 _amountIn, bytes calldata)
    external
    override
    returns (LocalQuote memory _quote)
  {
    if (_tokenIn == _tokenOut) {
      revert UnsupportedRoute(_tokenIn, _tokenOut);
    }

    if (_amountIn == 0 || _amountIn > uint256(type(int256).max)) {
      revert InvalidAmount();
    }

    try POOL_MANAGER.unlock(
      abi.encode(
        UnlockData({
          route: address(0),
          inbox: address(0),
          tokenIn: _tokenIn,
          tokenOut: _tokenOut,
          amountIn: _amountIn,
          quote: true,
          sqrtPriceLimitX96: 0
        })
      )
    ) returns (
      bytes memory
    ) {
      revert InvalidUniswapQuote();
    } catch (bytes memory reason) {
      return UniswapQuote.decode(reason);
    }
  }

  /// @notice Executes a Uniswap v4 exact-input swap. `_amountIn == 0` uses the full inbox balance.
  /// @dev `_adapterCalldata` is empty, `abi.encode(uint256 minAmountOut)` or
  /// `abi.encode(uint256 minAmountOut, uint160 sqrtPriceLimitX96)`. `minAmountOut` is checked against the inbox
  /// balance increase. The price limit is in pool terms (sqrt of currency1 per currency0, native is `address(0)` and so
  /// always currency0): when the token in is currency0 (`zeroForOne`) it must be below the current price, otherwise
  /// above it, or the pool manager reverts. Partial fills always revert.
  function execute(
    address _inbox,
    address _tokenIn,
    address _tokenOut,
    uint256 _amountIn,
    bytes calldata _adapterCalldata
  ) external override returns (uint256 _amountOut) {
    if (_tokenIn == _tokenOut) {
      revert UnsupportedRoute(_tokenIn, _tokenOut);
    }

    (uint256 minAmountOut, uint160 sqrtPriceLimitX96) = SwapLimits.decode(_adapterCalldata);
    uint256 balanceBefore = minAmountOut == 0 ? 0 : _inboxAssetBalance(_inbox, _tokenOut);
    uint256 amountIn = _resolveAmountIn(_amountIn, _inboxAssetBalance(_inbox, _tokenIn));
    if (amountIn == 0 || amountIn > uint256(type(int256).max)) {
      revert InvalidAmount();
    }

    bytes memory result = POOL_MANAGER.unlock(
      abi.encode(
        UnlockData({
          route: msg.sender,
          inbox: _inbox,
          tokenIn: _tokenIn,
          tokenOut: _tokenOut,
          amountIn: amountIn,
          quote: false,
          sqrtPriceLimitX96: sqrtPriceLimitX96
        })
      )
    );
    _amountOut = abi.decode(result, (uint256));
    if (minAmountOut != 0) {
      SwapLimits.requireMinAmountOut(balanceBefore, _inboxAssetBalance(_inbox, _tokenOut), minAmountOut);
    }

    emit UniswapV4RouteExecuted(_inbox, _tokenIn, _tokenOut, FEE, TICK_SPACING, HOOKS, amountIn, _amountOut);
  }

  /// @inheritdoc IUniswapV4UnlockCallback
  function unlockCallback(bytes calldata _data) external returns (bytes memory _result) {
    if (msg.sender != address(POOL_MANAGER)) {
      revert UnauthorizedPoolManager(msg.sender);
    }

    UnlockData memory data = abi.decode(_data, (UnlockData));
    UniswapV4PoolKey memory key = _poolKey(data.tokenIn, data.tokenOut);
    bool zeroForOne = data.tokenIn == key.currency0;

    int256 swapDelta = POOL_MANAGER.swap(
      key,
      UniswapV4SwapParams({
        zeroForOne: zeroForOne,
        amountSpecified: -int256(data.amountIn),
        sqrtPriceLimitX96: data.sqrtPriceLimitX96 == 0 ? _sqrtPriceLimit(zeroForOne) : data.sqrtPriceLimitX96
      }),
      ""
    );

    int128 inputDelta = zeroForOne ? _amount0(swapDelta) : _amount1(swapDelta);
    int128 outputDelta = zeroForOne ? _amount1(swapDelta) : _amount0(swapDelta);
    uint256 amountOwed = _negativeDelta(inputDelta, swapDelta);
    if (amountOwed != data.amountIn) {
      revert InvalidConsumedAmount(data.amountIn, amountOwed);
    }

    uint256 amountOut = _positiveDelta(outputDelta, swapDelta);
    if (data.quote) {
      UniswapQuote.revertQuote(amountOwed, amountOut);
    }

    _settleInput(data.route, data.inbox, data.tokenIn, amountOwed);
    POOL_MANAGER.take(data.tokenOut, data.inbox, amountOut);

    return abi.encode(amountOut);
  }

  function _settleInput(address _route, address _inbox, address _token, uint256 _amount) internal {
    POOL_MANAGER.sync(_token);

    if (_token == address(0)) {
      bytes memory result = _executeInboxTransactionFromRoute(
        _route, _inbox, address(POOL_MANAGER), _amount, abi.encodeCall(IUniswapV4PoolManager.settleFor, (address(this)))
      );
      uint256 settled = abi.decode(result, (uint256));
      if (settled != _amount) {
        revert InvalidSettlementAmount(_amount, settled);
      }
    } else {
      _executeInboxTokenTransferFromRoute(_route, _inbox, _token, address(POOL_MANAGER), _amount);
      uint256 settled = POOL_MANAGER.settle();
      if (settled != _amount) {
        revert InvalidSettlementAmount(_amount, settled);
      }
    }
  }

  function _poolKey(address _tokenIn, address _tokenOut) internal view returns (UniswapV4PoolKey memory _key) {
    (address currency0, address currency1) = _tokenIn < _tokenOut ? (_tokenIn, _tokenOut) : (_tokenOut, _tokenIn);
    _key =
      UniswapV4PoolKey({currency0: currency0, currency1: currency1, fee: FEE, tickSpacing: TICK_SPACING, hooks: HOOKS});
  }

  function _amount0(int256 _swapDelta) internal pure returns (int128 _amount) {
    assembly ("memory-safe") {
      _amount := sar(128, _swapDelta)
    }
  }

  function _amount1(int256 _swapDelta) internal pure returns (int128 _amount) {
    assembly ("memory-safe") {
      _amount := signextend(15, _swapDelta)
    }
  }

  function _negativeDelta(int128 _amount, int256 _swapDelta) internal pure returns (uint256) {
    if (_amount >= 0) {
      revert InvalidSwapDelta(_swapDelta);
    }

    return uint256(-int256(_amount));
  }

  function _positiveDelta(int128 _amount, int256 _swapDelta) internal pure returns (uint256) {
    if (_amount <= 0) {
      revert InvalidSwapDelta(_swapDelta);
    }

    return uint256(int256(_amount));
  }

  function _sqrtPriceLimit(bool _zeroForOne) internal pure returns (uint160) {
    return _zeroForOne ? MIN_SQRT_RATIO + 1 : MAX_SQRT_RATIO - 1;
  }

  function _isValidFee(uint24 _fee) internal pure returns (bool) {
    return _fee <= MAX_LP_FEE || _fee == DYNAMIC_FEE_FLAG;
  }

  function _isDynamicFee(uint24 _fee) internal pure returns (bool) {
    return _fee == DYNAMIC_FEE_FLAG;
  }

  function _validateHooks(uint24 _fee, address _hooks) internal pure {
    if (_hooks == address(0)) {
      return;
    }

    uint160 flags = uint160(_hooks) & ALL_HOOK_MASK;
    if (flags == 0 && !_isDynamicFee(_fee)) {
      revert InvalidHooks(_hooks);
    }
    if (((flags & AFTER_ADD_LIQUIDITY_RETURNS_DELTA_FLAG) != 0) && ((flags & AFTER_ADD_LIQUIDITY_FLAG) == 0)) {
      revert InvalidHooks(_hooks);
    }
    if (((flags & AFTER_REMOVE_LIQUIDITY_RETURNS_DELTA_FLAG) != 0) && ((flags & AFTER_REMOVE_LIQUIDITY_FLAG) == 0)) {
      revert InvalidHooks(_hooks);
    }
    if (((flags & BEFORE_SWAP_RETURNS_DELTA_FLAG) != 0) && ((flags & BEFORE_SWAP_FLAG) == 0)) {
      revert InvalidHooks(_hooks);
    }
    if (((flags & AFTER_SWAP_RETURNS_DELTA_FLAG) != 0) && ((flags & AFTER_SWAP_FLAG) == 0)) {
      revert InvalidHooks(_hooks);
    }
  }
}

