  bool zeroForOne;
  int256 amountSpecified;
  uint160 sqrtPriceLimitX96;
}

/// @title IUniswapV4PoolManager
/// @author Agustin Aguilar
/// @notice Minimal Uniswap v4 PoolManager interface
interface IUniswapV4PoolManager {
  function unlock(bytes calldata _data) external returns (bytes memory _result);

  function swap(UniswapV4PoolKey memory _key, UniswapV4SwapParams memory _params, bytes calldata _hookData)
    external
    returns (int256 _swapDelta);

  function sync(address _currency) external;

  function take(address _currency, address _to, uint256 _amount) external;

  function settle() external payable returns (uint256 _paid);

  function settleFor(address _recipient) external payable returns (uint256 _paid);
}

